 const proteins=[['Thịt heo','pork','pork',500],['Thịt gà','chicken','chicken',600],['Thịt bò','beef','beef',500],['Cá trắng','fish','fish',600],['Cá hồi','salmon','fish',550],['Tôm','shrimp','shrimp',550],['Đậu hũ','tofu','plant',650]];
